-- Round 20: fixes and completes July's historical sales.
-- Generated by scripts/historical/build_import_round20.py -- see that file's
-- docstring for the full story and parse_sheet_round20.py for how this data
-- was pulled from the spreadsheet's own complete "MONTHLY SUMMARY JULY"
-- table (reconciled exactly against the sheet's own printed July totals).
--
-- Step 1: the 6 rows Round 14 imported for 2026-07-07 were an incomplete
-- partial transcription (6 of that day's real 35 line items). Replace the
-- whole day outright rather than risk a silent duplicate or gap trying to
-- diff/merge the old 6 against the correct 35.
delete from historical_sales where sale_date = '2026-07-07';

-- Step 2: insert the complete, correct 2026-07-07 through 2026-07-31 data
-- (400 rows: 35 for the 7th + 365 for the 8th-31st).
-- 2026-07-01 through 2026-07-06 are untouched -- already correctly imported
-- in Round 14 (verified byte-for-byte identical against this same source).
-- Safe to re-run: source_row_id is fixed per row, so on conflict do nothing.
on conflict (source_row_id) do nothing;
